const btnFinish = document.getElementById("btnFinish");
const btnRestart = document.getElementById("btnRestart");
const progressBar = document.getElementById("progressBar");

// ================= построение теста =================
function el(tag, cls, text) {
  const n = document.createElement(tag);
  if (cls) n.className = cls;
  if (text != null) n.textContent = text;
  return n;
}

function buildTest() {
  stepsEl.innerHTML = "";
  panesEl.innerHTML = "";

  STEP_NAMES.forEach((name, idx) => {
    const t = el("button", "tab", name);
    t.type = "button";
    t.setAttribute("role", "tab");
    t.setAttribute("data-step-btn", String(idx));
    t.addEventListener("click", () => setStep(idx));
    stepsEl.appendChild(t);
  });

  for (let s = 0; s < STEPS; s++) {
    const pane = el("div", "pane");
    pane.setAttribute("data-step-pane", String(s));
    pane.setAttribute("role", "tabpanel");
    const grid = el("div", "grid");
    for (let c = 0; c < PER_STEP; c++) {
      const listDef = DATA[s * PER_STEP + c];
      const card = el("div", "qcard");
      const title = el("div", "qcard__title", "Я наиболее");
      const ul = el("ul", "list");
      listDef.forEach(([word, type]) => {
        const li = el("li", null, word);
        li.setAttribute("data-type", type);
        li.innerHTML = HANDLE_SVG;
        li.appendChild(document.createTextNode(word));
        ul.appendChild(li);
      });
      const foot = el("div", "qcard__foot", "Я наименее");
      card.append(title, ul, foot);
      grid.appendChild(card);
    }
    panesEl.appendChild(pane);
  }
  // sortable по всем спискам
  panesEl.querySelectorAll(".list").forEach(ul => {
    if (!ul.__discSortable) makeSortable(ul);
  });
}

